## ID/EX Pipeline Register

```systemverilog
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n || flush_id_ex) begin
        id_ex_reg_write  <= 1'b0;   id_ex_mem_read   <= 1'b0;
        id_ex_mem_write  <= 1'b0;   id_ex_branch     <= 1'b0;
        id_ex_jump       <= 1'b0;   id_ex_alu_srcA   <= 1'b0;
        id_ex_alu_srcB   <= 2'b00;  id_ex_wb_sel     <= 2'b00;
        id_ex_alu_op     <= 4'b0;   id_ex_rs1_data   <= 32'b0;
        id_ex_rs2_data   <= 32'b0;  id_ex_store_data <= 32'b0;
        id_ex_imm        <= 32'b0;  id_ex_pc         <= 32'b0;
        id_ex_pc_plus4   <= 32'b0;  id_ex_rd         <= 5'b0;
        id_ex_rs1        <= 5'b0;   id_ex_rs2        <= 5'b0;
        id_ex_funct3     <= 3'b0;   id_ex_opcode     <= 7'b0;
    end else begin
        id_ex_reg_write  <= id_reg_write;
        id_ex_mem_read   <= id_mem_read;
        id_ex_mem_write  <= id_mem_write;
        id_ex_branch     <= id_branch;
        id_ex_jump       <= id_jump;
        id_ex_alu_srcA   <= id_alu_srcA;
        id_ex_alu_srcB   <= id_alu_srcB;
        id_ex_wb_sel     <= id_wb_sel;
        id_ex_alu_op     <= id_alu_op_out;
        id_ex_rs1_data   <= id_rs1_data_out;
        id_ex_rs2_data   <= id_rs2_data_out;
        id_ex_store_data <= id_store_data;
        id_ex_imm        <= id_imm;
        id_ex_pc         <= id_pc_out;
        id_ex_pc_plus4   <= id_pc_plus4_out;
        id_ex_rd         <= id_rd;
        id_ex_rs1        <= id_rs1;
        id_ex_rs2        <= id_rs2;
        id_ex_funct3     <= id_funct3;
        id_ex_opcode     <= id_opcode;
    end
end
